<?php
namespace Tests\Feature;use App\Models\PasswordResetSession;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class AuthenticationFlowTest extends TestCase{use RefreshDatabase;private function user():User{return User::create(['public_id'=>(string)Str::ulid(),'identity_region'=>'ap-south-1','first_name'=>'Asha','display_name'=>'Asha Rao','email_encrypted'=>'encrypted','email_hash'=>str_repeat('a',64),'email_masked'=>'a***@example.com','phone_encrypted'=>'encrypted','phone_hash'=>str_repeat('b',64),'phone_masked'=>'+91 ******1234','password'=>'OldPassword!23','status'=>'active','registered_via'=>'self','registration_started_at'=>now()]);}public function test_authenticated_user_can_change_password():void{$u=$this->user();Sanctum::actingAs($u);$this->postJson('/api/v1/auth/change-password',['current_password'=>'OldPassword!23','password'=>'NewPassword!45','password_confirmation'=>'NewPassword!45'])->assertOk();$this->assertTrue(Hash::check('NewPassword!45',$u->refresh()->password));}public function test_reset_token_is_single_use():void{$u=$this->user();$raw=Str::random(64);$s=PasswordResetSession::create(['public_id'=>(string)Str::ulid(),'user_id'=>$u->id,'session_token_hash'=>hash('sha256',Str::random()),'reset_token_hash'=>hash('sha256',$raw),'expires_at'=>now()->addMinutes(15),'reset_token_expires_at'=>now()->addMinutes(15)]);$payload=['token'=>$s->public_id.'.'.$raw,'password'=>'NewPassword!45','password_confirmation'=>'NewPassword!45'];$this->postJson('/api/v1/auth/reset-password',$payload)->assertOk();$this->postJson('/api/v1/auth/reset-password',$payload)->assertNotFound();}}
